  { zoom: 1.2, ox: 0.25, oy: -0.15 },
  { zoom: 1.6, ox: -0.15, oy: 0.4 },
];

export function defaultPanel(photoIndex, slot = 0) {
  const crop = CROPS[slot % CROPS.length];
  return { photo: photoIndex, zoom: crop.zoom, ox: crop.ox, oy: crop.oy, flip: false };
}

